+        'fibonacci' { Write-Output ('Fibonacci({0}) = {1}' -f $N, (Get-Fibonacci -N $N)) }
+        'factorial' { Write-Output ('Factorial({0}) = {1}' -f $N, (Get-Factorial -N $N)) }
+        default { throw "Unsupported operation '$Operation'." }
+    }
 }

